/**
 * Shared layout for every Reporty email: the app notifications sent through Resend and the
 * Supabase Auth templates generated by `scripts/generate-auth-email-templates.ts`.
 *
 * Email clients ignore CSS variables and most modern CSS, so the theme tokens from
 * `app/globals.css` live here as hex values and the markup uses tables with inline styles.
 * No `server-only` marker: the generator script imports this module outside Next.
 */

/** `app/globals.css` tokens converted from OKLCH to hex. */
export const EMAIL_COLORS = {
  background: "#eeecec",
  card: "#ffffff",
  foreground: "#15140f",
  mutedForeground: "#495a4f",
  subtle: "#f2f2f2",
  border: "#dcdcdc",
  primary: "#278c5a",
  accent: "#d8eee0",
  accentForeground: "#163524",
  destructive: "#cc3d3d",
  destructiveSurface: "#fbeaea",
  info: "#297cae",
  infoSurface: "#e4f0f7",
  button: "#000000",
} as const

export const EMAIL_LOGO_URL = "https://reporty.com.ar/logos/logoSinBg.png"

const FONT_STACK = "Geist, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif"

export type EmailTone = "success" | "danger" | "info"

const TONES: Record<EmailTone, { color: string; surface: string }> = {
  success: { color: EMAIL_COLORS.primary, surface: EMAIL_COLORS.accent },
  danger: { color: EMAIL_COLORS.destructive, surface: EMAIL_COLORS.destructiveSurface },
  info: { color: EMAIL_COLORS.info, surface: EMAIL_COLORS.infoSurface },
}

export function escapeHtml(value: string) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;")
}

/** A paragraph of body copy. `html` must already be escaped. */
export function emailParagraph(html: string) {
  return `<p style="margin:0 0 16px 0;font-size:16px;line-height:1.6;color:${EMAIL_COLORS.mutedForeground};">${html}</p>`
}

/** Uppercase status pill, like the report state badges in the app. */
export function emailPill(label: string, tone: EmailTone) {
  return `<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:${TONES[tone].color};color:#ffffff;font-size:12px;font-weight:700;letter-spacing:0.6px;">${escapeHtml(label.toLocaleUpperCase("es"))}</span>`
}

/**
 * Highlighted block for the report the email talks about. `title` is plain text; `content`
 * is already-escaped HTML placed under it.
 */
export function emailPanel({ title, content, tone }: { title: string; content?: string; tone?: EmailTone }) {
  const accent = tone ? TONES[tone].color : EMAIL_COLORS.border
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:8px 0 24px 0;border-collapse:separate;">
  <tr>
    <td style="padding:20px;border-radius:12px;background:${EMAIL_COLORS.subtle};border-left:4px solid ${accent};">
      <p style="margin:0;font-size:17px;font-weight:600;line-height:1.4;color:${EMAIL_COLORS.foreground};">${escapeHtml(title)}</p>
      ${content ?? ""}
    </td>
  </tr>
</table>`
}

/** A labelled value inside a panel, such as the new state or a comment. `value` is escaped HTML. */
export function emailField(label: string, value: string) {
  return `<p style="margin:16px 0 4px 0;font-size:12px;font-weight:600;letter-spacing:0.6px;text-transform:uppercase;color:${EMAIL_COLORS.mutedForeground};">${escapeHtml(label)}</p>
      <p style="margin:0;font-size:15px;line-height:1.6;color:${EMAIL_COLORS.foreground};white-space:pre-wrap;">${value}</p>`
}

/** Black pill call to action, the main control style of the app. */
export function emailButton(label: string, href: string) {
  return `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:8px auto 8px auto;">
  <tr>
    <td style="border-radius:999px;background:${EMAIL_COLORS.button};">
      <a href="${href}" style="display:inline-block;padding:14px 32px;border-radius:999px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;">${escapeHtml(label)}</a>
    </td>
  </tr>
</table>`
}

type EmailLayoutOptions = {
  /** Document title and accessible name. */
  title: string
  /** Inbox preview text shown next to the subject. */
  preheader: string
  heading: string
  /** Escaped HTML built with the helpers above. */
  body: string
  /** Small print under the card. Escaped HTML. */
  footnote?: string
}

export function renderEmailLayout({ title, preheader, heading, body, footnote }: EmailLayoutOptions) {
  return `<!DOCTYPE html>
<html lang="es">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="color-scheme" content="light">
    <title>${escapeHtml(title)}</title>
  </head>
  <body style="margin:0;padding:0;background:${EMAIL_COLORS.background};font-family:${FONT_STACK};">
    <div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(preheader)}</div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${EMAIL_COLORS.background};">
      <tr>
        <td align="center" style="padding:24px 12px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;">
            <tr>
              <td align="center" style="padding:4px 0 16px 0;">
                <img src="${EMAIL_LOGO_URL}" width="150" alt="Reporty" style="display:block;width:150px;height:auto;border:0;">
              </td>
            </tr>
            <tr>
              <td style="padding:32px 28px;background:${EMAIL_COLORS.card};border:1px solid ${EMAIL_COLORS.border};border-radius:24px;">
                <h1 style="margin:0 0 16px 0;font-size:22px;font-weight:700;line-height:1.3;color:${EMAIL_COLORS.foreground};">${escapeHtml(heading)}</h1>
                ${body}
              </td>
            </tr>
            <tr>
              <td align="center" style="padding:20px 16px 0 16px;font-size:12px;line-height:1.6;color:${EMAIL_COLORS.mutedForeground};">
                ${footnote ? `<p style="margin:0 0 8px 0;">${footnote}</p>` : ""}
                <p style="margin:0;"><strong style="color:${EMAIL_COLORS.primary};">Reporty</strong> · Reportes ciudadanos de Posadas</p>
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`
}
